<?php
declare(strict_types=1);
$base=realpath((string)getenv('HOME').'/domains/brebobv.nl/office_calc_test');if($base===false)exit(2);$config=require $base.'/config/config.php';$root=realpath((string)($config['OFFICE_PRIVATE_ROOT']??''));if(!is_array($config)||($config['OFFICE_BASE_PATH']??'')!=='/office-test'||$root===false||!str_starts_with($root,$base.'/release-')||!str_ends_with($root,'/private'))exit(3);
$files=glob($root.'/public/*calc*.php')?:[];$files[]=$root.'/src/Calculation/OfficeCalcCrmDraftLineRepository.php';$files[]=(string)getenv('HOME').'/domains/brebobv.nl/public_html/office-test/index.php';
foreach(array_unique($files)as$file){if(!is_file($file))continue;$body=(string)file_get_contents($file);echo 'CALC_FILE='.basename($file).' SHA256='.hash('sha256',$body)."\n";preg_match_all("~['\"]([^'\"\\r\\n]*(?:calc|workbench)[^'\"\\r\\n]*\\.php)['\"]~i",$body,$matches);foreach(array_unique($matches[1]??[])as$ref)echo 'CALC_INCLUDE.'.basename($file).'='.basename($ref)."\n";echo 'CALC_WRITER.'.basename($file).'='.(str_contains($body,'OfficeCalcCrmDraftLineRepository')?'DRAFT_REPOSITORY':'OTHER')."\n";}
foreach(['OFFICE_CALC_CRM_DRAFT_LAUNCH_ENABLED','OFFICE_CALC_CRM_SCHEMA_VERIFIED','OFFICE_CALC_DRAFT_COLLABORATION_ENABLED']as$key)echo $key.'='.(($config[$key]??'')==='enabled'?'ENABLED':'DISABLED')."\n";
$db=new PDO((string)$config['OFFICE_INTAKE_PDO_DSN'],(string)$config['OFFICE_INTAKE_DB_USER'],(string)$config['OFFICE_INTAKE_DB_PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$db->exec('SET SESSION TRANSACTION READ ONLY');$db->beginTransaction();
foreach(['office_calc_crm_drafts','calculation_versions','calculation_lines']as$table){$q=$db->prepare('SELECT COLUMN_NAME,COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? ORDER BY ORDINAL_POSITION');$q->execute([$table]);echo 'CALC_COLUMNS.'.$table.'='.implode(',',array_map(static fn(array $row):string=>$row['COLUMN_NAME'].':'.$row['COLUMN_TYPE'],$q->fetchAll(PDO::FETCH_ASSOC)))."\n";}$db->rollBack();echo "CALC_COLLAB_INSPECTION=READ_ONLY\n";
